      <div class="score-num" aria-hidden="true">${score}/${total}</div>
      <div class="score-body">
        <div class="score-headline">${headline}</div>
        <div class="score-detail">${detail}</div>
      </div>
    </div>
  `;
}

function getHeadline(score, total) {
  if (score === total) return '🎉 Perfect score!';
  if (score >= total * 0.7) return '👍 Well done!';
  if (score >= total * 0.4) return '📚 Keep studying!';
  return '💡 Better luck next time!';
}

function resetQuiz() {
  // Clear result state from options
  form.querySelectorAll('.option').forEach((optionEl) => {
    optionEl.classList.remove('is-correct', 'is-incorrect', 'is-missed');
    const badge = optionEl.querySelector('.result-badge');
    if (badge) badge.remove();
  });

  // Re-enable and uncheck checkboxes
  form.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
    cb.disabled = false;
    cb.checked = false;
  });

  form.classList.remove('quiz-submitted');
  statusEl.innerHTML = '';

  // Restore submit button
  const actionsEl = form.querySelector('.form-actions');
  actionsEl.innerHTML = '';
  const submitBtn = document.createElement('button');
  submitBtn.type = 'submit';
  submitBtn.className = 'btn btn-primary';
  submitBtn.textContent = 'Submit Quiz';
  actionsEl.appendChild(submitBtn);

  // Return focus to the first question
  form.querySelector('input[type="checkbox"]').focus();
}
