  const runAxe = async (label) => {
    await page.addScriptTag({ path: '/tmp/axe.min.js' });
    await page.waitForFunction('typeof window.axe !== "undefined"');
    const r = await page.evaluate(async () => {
      const res = await window.axe.run();
      return {
        violations: res.violations.map(v => ({
          id: v.id, impact: v.impact, help: v.help,
          tags: v.tags,
          targets: v.nodes.map(n => n.target)
        }))
      };
    });
    const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
    const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));
    console.log(`\n=== ${label} ===`);
    console.log('WCAG violations:', wcag.length);
    if (wcag.length) console.log(JSON.stringify(wcag, null, 2));
    console.log('Best-practice:', bp.length);
    if (bp.length) bp.forEach(v => console.log(' bp:', v.id, v.targets));
    return wcag.length;
  };

  // State 1: initial load
  await page.setContent(html, { waitUntil: 'load' });
  const v1 = await runAxe('Initial page');

  // State 2: check some boxes
  await page.check('input[name="q1"][value="python"]');
  await page.check('input[name="q1"][value="c"]'); // wrong answer
  const v2 = await runAxe('After selecting answers');

  // State 3: submit
  await page.click('button[type="submit"]');
  await page.waitForSelector('.score-banner');
  const v3 = await runAxe('After submit (results shown)');

  await browser.close();

  const total = v1 + v2 + v3;
  console.log(`\n=== SUMMARY: ${total} WCAG violations total ===`);
  process.exit(total ? 1 : 0);
})();
EOF
