function hexToRgb(h) {
  const n = parseInt(h.replace('#',''), 16);
  return [n>>16&255, n>>8&255, n&255];
}
function lin(c) { c/=255; return c<=0.04045 ? c/12.92 : Math.pow((c+0.055)/1.055, 2.4); }
function lum([r,g,b]) { return 0.2126*lin(r) + 0.7152*lin(g) + 0.0722*lin(b); }
function cr(c1,c2) { const [l1,l2] = [lum(c1),lum(c2)].sort((a,b)=>b-a); return (l1+0.05)/(l2+0.05); }

const pairs = [
  ['text on white',         '#18192b','#ffffff'],
  ['help text on help-bg',  '#52536b','#f7f7fd'],
  ['btn text on primary',   '#ffffff','#5046e5'],
  ['correct badge txt/bg',  '#166534','#dcfce7'],
  ['incorrect badge txt/bg','#991b1b','#fee2e2'],
  ['missed badge txt/bg',   '#166534','#dcfce7'],
  ['score num on pri-light','#5046e5','#eeedfd'],
  ['legend on card bg',     '#18192b','#ffffff'],
];
pairs.forEach(([lbl,fg,bg]) => {
  const r = cr(hexToRgb(fg), hexToRgb(bg));
  const pass = r >= 4.5 ? 'PASS' : r >= 3.0 ? 'LARGE-OK' : 'FAIL';
  console.log(pass, r.toFixed(2), lbl);
});
